WITH ${CP_HIER_CTE}
          SELECT
            ${dateTrunc}             AS period,
            ${selectProduct}
            ${selectStore}
            SUM(${amtCol})           AS amount,
            SUM(sd.quantity)         AS quantity
          FROM sales_header sh
          JOIN sales_detail sd ON sd.header_id = sh.id
          JOIN products p      ON p.id = sd.product_id
          JOIN cp_hier         ON cp_hier.product_id = p.id
          LEFT JOIN branches b ON b.id = sh.branch_id
          WHERE sh.doc_date IS NOT NULL
            AND sh.doc_date >= $1::date
            AND sh.doc_date <  ($2::date + INTERVAL '1 day')
            ${branchFilter}
            ${catFilter}
          GROUP BY ${groupByClause}
          ORDER BY period ASC, ${gp ? "p.name ASC," : ""} ${gs ? "b.sap_id ASC" : "1"}

SELECT COUNT(*)::int AS total
         FROM public.products p
         WHERE 1=1 ${brandClause}
           ${countClauses.join(" ")}

SELECT
           ${selectProduct}
           ${selectStore}
           SUM(sd.quantity)::numeric                     AS cantidad,
           ROUND(SUM(${amtColExport})::numeric, 2)              AS monto,
           COUNT(DISTINCT sh.id)::int                    AS tickets
         FROM public.sales_detail sd
         JOIN public.products p ON p.id = sd.product_id
         JOIN public.sales_header sh ON sh.id = sd.header_id
         JOIN public.branches b ON b.id = sh.branch_id
         WHERE 1=1 ${brandClause}
           AND sh.doc_date >= $${fromIdx}::date AND sh.doc_date < ($${toIdx}::date + INTERVAL '1 day')
           ${clauses.join(" ")}
         GROUP BY ${groupByDims}
         ORDER BY monto DESC
         LIMIT 10000

SELECT
          ${dateTrunc} AS period,
          ${selectProduct}
          ${selectStore}
          SUM(${amtCol}) AS amount,
          SUM(sd.quantity) AS quantity
        FROM public.sales_header sh
        JOIN public.sales_detail sd ON sd.header_id = sh.id
        JOIN public.products p ON p.id = sd.product_id
        LEFT JOIN public.branches b ON b.id = sh.branch_id
        WHERE sh.doc_date IS NOT NULL
          AND sh.doc_date >= $${fromIdx}::date AND sh.doc_date < ($${toIdx}::date + INTERVAL '1 day')
          ${brandClause}
          ${clauses.join(' ')}
        GROUP BY ${groupByClause}
        ORDER BY period ASC, ${gp ? 'p.name ASC,' : ''} ${gs ? 'b.sap_id ASC' : '1'}

SELECT
           ${selectProduct}
           ${selectStore}
           SUM(sd.quantity)::numeric                     AS cantidad,
           ROUND(SUM(sd.total)::numeric, 2)              AS monto,
           COUNT(DISTINCT sh.id)::int                    AS tickets
         FROM public.sales_detail sd
         JOIN public.products p ON p.id = sd.product_id
         JOIN public.sales_header sh ON sh.id = sd.header_id
         JOIN public.branches b ON b.id = sh.branch_id
         WHERE p.id IN ${SUPPLIER_PRODUCTS_SUBQUERY}
           AND sh.doc_date >= $2::date AND sh.doc_date < ($3::date + INTERVAL '1 day')
           ${clauses.join(" ")}
         GROUP BY ${groupByDims}
         ORDER BY monto DESC
         LIMIT 10000

SELECT
          ${dateTrunc} AS period,
          ${selectProduct}
          ${selectStore}
          SUM(${amtCol}) AS amount,
          SUM(sd.quantity) AS quantity
        FROM public.sales_header sh
        JOIN public.sales_detail sd ON sd.header_id = sh.id
        JOIN public.products p ON p.id = sd.product_id
        LEFT JOIN public.branches b ON b.id = sh.branch_id
        WHERE sh.doc_date IS NOT NULL
          AND sh.doc_date >= $2::date AND sh.doc_date < ($3::date + INTERVAL '1 day')
          AND p.id IN ${SUPPLIER_PRODUCTS_SUBQUERY}
          ${productFilter}
          ${branchFilter}
        GROUP BY ${groupByClause}
        ORDER BY period ASC, ${gp ? 'p.name ASC,' : ''} ${gs ? 'b.sap_id ASC' : '1'}
